style.css:
/* 1. Hide EVERYTHING */
body * {
    opacity: 0 !important;
    transition: opacity 0.1s linear;
    pointer-events: auto !important; /* still hoverable */
}

/* 2. Reveal ONLY the exact hovered element */
body *:hover {
    opacity: 1 !important;
}

/* 3. Do NOT reveal children */
body *:hover * {
    opacity: 0 !important;  /* CHILDREN STAY HIDDEN */
}

/* 4. Do NOT reveal parents */
body *:hover {
    transition-delay: 0s !important;
}
